end

local Tab = {}
Tab.__index = Tab
function Tab:CreateSection(name)
    local root = make("Frame", { Name = name, BackgroundTransparency = 1, Size = UDim2.new(1, -4, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = self._count }, self.Page)
    self._count = self._count + 1
